const GN=GW*GH, aA=S.a,bA=S.b,ta=S.ta,tb=S.tb,vxF=S.vx,vyF=S.vy,voF=S.vo,buf=S.buf;
if(S.seedUsed!==(P.seed|0)){S.seedUsed=(P.seed|0); S.syph=hsh(9)*TAU;}

